    int pt_arith = (ptype->kind == TY_INT || ptype->kind == TY_FLOAT);
    if (!at_arith || !pt_arith) return;
    if (at->kind == ptype->kind && at->width == ptype->width
        && at->is_unsigned == ptype->is_unsigned)
        return;
