            if (lt.kind != TY_INT)
                die_at(e->loc.file, e->loc.line, e->loc.col,
                       "left operand of '%s' must be integer",
                       op == BOP_BITAND ? "&" : op == BOP_BITOR ? "|" : "^");
            if (rt.kind != TY_INT)
                die_at(e->loc.file, e->loc.line, e->loc.col,
                       "right operand of '%s' must be integer",
                       op == BOP_BITAND ? "&" : op == BOP_BITOR ? "|" : "^");
